try_node = try_nodes[0]
if len(try_node.handlers) < 3:
    raise AssertionError('Your try block should have at least 3 except handlers')

# Check for specific exception types
exception_names = []
for handler in try_node.handlers:
    if handler.type:
        exception_names.append(handler.type.id)

if 'FileNotFoundError' not in exception_names:
